#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# gen-dart.sh — regenerate Flutter Dart protobuf stubs.
#
# Why this exists (see buf.gen.dart.yaml header):
#   buf's `local:` resolver cannot exec protoc-gen-dart.bat, so Dart stubs
#   must be generated by invoking protoc directly with the Pub-installed
#   plugin on PATH.
#
# Output:  ../client/lib/proto/  (.pb.dart / .pbenum.dart / .pbjson.dart /
#                                .pbgrpc.dart per .proto)
# Run from: yucai/proto/   (or via `make gen-dart` from yucai/)
#
# Requires:
#   - protoc on PATH (libprotoc 25+) WITH the well-known-type protos
#     resolvable (see PROTOC_INCLUDE below — a bare protoc binary without
#     its include/ directory does NOT resolve google/protobuf/*.proto)
#   - protoc_plugin 25.0.0  (`dart pub global activate protoc_plugin 25.0.0`)
#     → installs protoc-gen-dart.bat under %LOCALAPPDATA%\Pub\Cache\bin
#       (Linux/macOS: ~/.pub-cache/bin/protoc-gen-dart, no extension)
# ---------------------------------------------------------------------------
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

# Locate the protoc-gen-dart plugin. On Windows Pub installs it as a .bat;
# on Unix it is a no-extension executable. We just need its directory on PATH.
PUB_BIN_CANDIDATES=(
  "${LOCALAPPDATA:-}/Pub/Cache/bin"          # Windows
  "${HOME:-}/.pub-cache/bin"                 # Unix
  "${FLUTTER_ROOT:-}/bin/cache/dart-sdk/bin" # fallback
)
for c in "${PUB_BIN_CANDIDATES[@]}"; do
  if [[ -n "$c" && -d "$c" ]]; then
    case ":${PATH:-}:" in
      *":$c:"*) ;;
      *) export PATH="$c:${PATH:-}" ;;
    esac
  fi
done

if ! command -v protoc >/dev/null 2>&1; then
  echo "ERROR: protoc not found on PATH." >&2
  exit 1
fi

# Note: on Windows (Git Bash) `command -v`/`which` cannot locate `.bat`
# scripts, so we don't guard protoc-gen-dart here — if it is missing protoc
# itself will fail with a clear "protoc-gen-dart: program not found" error
# and the user will be pointed at `dart pub global activate protoc_plugin`.

OUT_DIR="../client/lib/proto"
mkdir -p "$OUT_DIR"

# Collect every .proto under the proto/ tree (flat or nested module dirs).
PROTO_FILES=()
while IFS= read -r -d '' f; do
  PROTO_FILES+=("$f")
done < <(find . -type f -name '*.proto' -print0)

if [[ ${#PROTO_FILES[@]} -eq 0 ]]; then
  echo "ERROR: no .proto files found under $SCRIPT_DIR" >&2
  exit 1
fi

# Locate the protoc-gen-dart plugin explicitly. Windows protoc's CreateProcess
# does NOT auto-append a `.bat` extension, so when the Pub-installed plugin is
# `protoc-gen-dart.bat` we must hand protoc the full path via --plugin (this is
# the same reason buf's `local:` resolver fails — see buf.gen.dart.yaml).
PLUGIN_FLAG=()
for name in protoc-gen-dart protoc-gen-dart.bat; do
  for c in "${PUB_BIN_CANDIDATES[@]}"; do
    [[ -z "$c" ]] && continue
    if [[ -f "$c/$name" ]]; then
      PLUGIN_FLAG=(--plugin="protoc-gen-dart=$c/$name")
      break 2
    fi
  done
done
if [[ ${#PLUGIN_FLAG[@]} -eq 0 ]] && ! command -v protoc-gen-dart >/dev/null 2>&1; then
  echo "ERROR: protoc-gen-dart plugin not found." >&2
  echo "       Run: dart pub global activate protoc_plugin" >&2
  exit 1
fi

echo "Generating Dart stubs for ${#PROTO_FILES[@]} proto file(s) → $OUT_DIR"
# Well-known-type include path (google/protobuf/*.proto): protoc resolves
# imports ONLY from -I paths (a bare binary like ~/go/bin/protoc carries no
# include/). Candidates: $PROTOC_INCLUDE override, then the official-release
# layout next to a protoc installed under ~/go/bin (~/go/include). Only WKT
# protos used by this tree are needed (any/empty/timestamp — see the raw
# imports); the dir is NOT part of this repo, so buf's Go generation stays
# untouched (buf has WKT built in).
WKT_INCLUDE_FLAG=()
for c in "${PROTOC_INCLUDE:-}" "${HOME:-}/go/include"; do
  [[ -n "$c" && -f "$c/google/protobuf/empty.proto" ]] || continue
  WKT_INCLUDE_FLAG=(-I "$c")
  break
done
if [[ ${#WKT_INCLUDE_FLAG[@]} -eq 0 ]]; then
  echo "WARNING: no well-known-type include dir found" >&2
  echo "         (set PROTOC_INCLUDE or place google/protobuf/*.proto" >&2
  echo "          under ~/go/include) — WKT imports will fail to resolve." >&2
fi

protoc \
  --proto_path=. \
  "${WKT_INCLUDE_FLAG[@]}" \
  "${PLUGIN_FLAG[@]}" \
  --dart_out="$OUT_DIR" \
  --dart_opt=grpc \
  "${PROTO_FILES[@]}"

echo "Done. Run 'cd client && dart analyze lib/proto/' to verify."
